// Dans SnapshotService (état partagé protégé par un verrou)
private func currentRailSettings() -> RailSettings {
    if let railSettings { return railSettings }
    let path = NSString(string: "~/.config/roadies/roadies.toml").expandingTildeInPath
    let stamp = fileModificationStamp(path)
    return railSettingsCache.withLock { cache in
        if let cached = cache.value, cache.stamp == stamp { return cached }
        let loaded = RailSettings.load()
        cache = (stamp, loaded)
        return loaded
    }
}

